public class Solution {
    public string AbbreviateProduct(int left, int right) {
        const long Mod = 100000;
        const long Limit = 10000000000L;

        int count2 = 0;
        int count5 = 0;
        long suffix = 1;
        long exact = 1;
        double logValue = 0.0;

        for (int i = left; i <= right; i++) {
            long value = i;

            while (value % 2 == 0) {
                count2++;
                value /= 2;
            }

            while (value % 5 == 0) {
                count5++;
                value /= 5;
            }

            suffix = suffix * (value % Mod) % Mod;
            logValue += System.Math.Log10(value);

            if (exact < Limit) {
                if (exact > (Limit - 1) / value)
                    exact = Limit;
                else
                    exact *= value;
            }
        }

        int trailingZeros = System.Math.Min(count2, count5);
        int remaining2 = count2 - trailingZeros;
        int remaining5 = count5 - trailingZeros;

        logValue += remaining2 * System.Math.Log10(2.0);
        logValue += remaining5 * System.Math.Log10(5.0);

        for (int i = 0; i < remaining2; i++) {
            suffix = suffix * 2 % Mod;

            if (exact < Limit) {
                if (exact > (Limit - 1) / 2)
                    exact = Limit;
                else
                    exact *= 2;
            }
        }

        for (int i = 0; i < remaining5; i++) {
            suffix = suffix * 5 % Mod;

            if (exact < Limit) {
                if (exact > (Limit - 1) / 5)
                    exact = Limit;
                else
                    exact *= 5;
            }
        }

        if (exact < Limit)
            return exact.ToString() + "e" + trailingZeros;

        double fractionalPart = logValue - System.Math.Floor(logValue);
        int prefix = (int)System.Math.Pow(10.0, fractionalPart + 4.0);

        return prefix.ToString() + "..." + suffix.ToString("D5") + "e" + trailingZeros;
    }
}
