using System.Collections.Generic;

public class Solution {
    public IList<string> AmbiguousCoordinates(string s) {
        var result = new List<string>();
        string digits = s.Substring(1, s.Length - 2);

        for (int split = 1; split < digits.Length; split++) {
            string left = digits.Substring(0, split);
            string right = digits.Substring(split);

            IList<string> leftForms = GenerateNumbers(left);
            IList<string> rightForms = GenerateNumbers(right);

            foreach (string x in leftForms) {
                foreach (string y in rightForms) {
                    result.Add("(" + x + ", " + y + ")");
                }
            }
        }

        return result;
    }

    private IList<string> GenerateNumbers(string digits) {
        var result = new List<string>();
        int n = digits.Length;

        if (n == 1 || digits[0] != '0') {
            result.Add(digits);
        }

        if (digits[n - 1] == '0') {
            return result;
        }

        for (int decimalPosition = 1; decimalPosition < n; decimalPosition++) {
            if (decimalPosition > 1 && digits[0] == '0') {
                break;
            }

            result.Add(
                digits.Substring(0, decimalPosition) + "." +
                digits.Substring(decimalPosition)
            );
        }

        return result;
    }
}
