public class Solution {
    private class UnionFind {
        private readonly int[] parent;
        private readonly int[] size;

        public UnionFind(int n) {
            parent = new int[n];
            size = new int[n];

            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int Find(int x) {
            if (parent[x] != x) {
                parent[x] = Find(parent[x]);
            }
            return parent[x];
        }

        public void Union(int a, int b) {
            int rootA = Find(a);
            int rootB = Find(b);

            if (rootA == rootB) {
                return;
            }

            if (size[rootA] < size[rootB]) {
                int temp = rootA;
                rootA = rootB;
                rootB = temp;
            }

            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        public int GetSize(int x) {
            return size[Find(x)];
        }
    }

    public int[] HitBricks(int[][] grid, int[][] hits) {
        int rows = grid.Length;
        int cols = grid[0].Length;
        int roof = rows * cols;

        int[][] remaining = new int[rows][];
        for (int r = 0; r < rows; r++) {
            remaining[r] = (int[])grid[r].Clone();
        }

        bool[] removed = new bool[hits.Length];

        for (int i = 0; i < hits.Length; i++) {
            int r = hits[i][0];
            int c = hits[i][1];

            if (remaining[r][c] == 1) {
                removed[i] = true;
                remaining[r][c] = 0;
            }
        }

        UnionFind unionFind = new UnionFind(rows * cols + 1);

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (remaining[r][c] == 0) {
                    continue;
                }

                int index = r * cols + c;

                if (r == 0) {
                    unionFind.Union(index, roof);
                }
                if (r > 0 && remaining[r - 1][c] == 1) {
                    unionFind.Union(index, (r - 1) * cols + c);
                }
                if (c > 0 && remaining[r][c - 1] == 1) {
                    unionFind.Union(index, r * cols + c - 1);
                }
            }
        }

        int[] result = new int[hits.Length];
        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };

        for (int i = hits.Length - 1; i >= 0; i--) {
            if (!removed[i]) {
                continue;
            }

            int r = hits[i][0];
            int c = hits[i][1];
            int index = r * cols + c;
            int stableBefore = unionFind.GetSize(roof);

            remaining[r][c] = 1;

            if (r == 0) {
                unionFind.Union(index, roof);
            }

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];

                if (nr >= 0 && nr < rows &&
                    nc >= 0 && nc < cols &&
                    remaining[nr][nc] == 1) {
                    unionFind.Union(index, nr * cols + nc);
                }
            }

            int stableAfter = unionFind.GetSize(roof);
            result[i] = System.Math.Max(0, stableAfter - stableBefore - 1);
        }

        return result;
    }
}
