public class Solution {
    public bool AreOccurrencesEqual(string s) {
        int[] frequencies = new int[26];

        foreach (char c in s) {
            frequencies[c - 'a']++;
        }

        int expected = 0;

        foreach (int frequency in frequencies) {
            if (frequency == 0) continue;

            if (expected == 0) {
                expected = frequency;
            } else if (frequency != expected) {
                return false;
            }
        }

        return true;
    }
}
