public class Solution {
    public int NumFactoredBinaryTrees(int[] arr) {
        const long Mod = 1_000_000_007;
        System.Array.Sort(arr);

        var counts = new System.Collections.Generic.Dictionary<int, long>();
        long answer = 0;

        foreach (int value in arr) {
            long trees = 1;

            foreach (int factor in arr) {
                if (factor >= value) break;

                if (value % factor == 0) {
                    int otherFactor = value / factor;

                    if (counts.TryGetValue(factor, out long leftCount) &&
                        counts.TryGetValue(otherFactor, out long rightCount)) {
                        trees = (trees + leftCount * rightCount) % Mod;
                    }
                }
            }

            counts[value] = trees;
            answer = (answer + trees) % Mod;
        }

        return (int)answer;
    }
}
