    public int CountVowelPermutation(int n) {
        const long Mod = 1_000_000_007;

        long a = 1;
        long e = 1;
        long i = 1;
        long o = 1;
        long u = 1;

        for (int length = 2; length <= n; length++) {
            long nextA = (e + i + u) % Mod;
            long nextE = (a + i) % Mod;
            long nextI = (e + o) % Mod;
            long nextO = i;
            long nextU = (i + o) % Mod;

            a = nextA;
            e = nextE;
            i = nextI;
            o = nextO;
            u = nextU;
        }

        return (int)((a + e + i + o + u) % Mod);
    }
}
