public class Solution {
    public int Clumsy(int n) {
        var stack = new System.Collections.Generic.Stack<int>();
        stack.Push(n);

        int operation = 0;

        for (int value = n - 1; value >= 1; value--) {
            switch (operation) {
                case 0:
                    stack.Push(stack.Pop() * value);
                    break;
                case 1:
                    stack.Push(stack.Pop() / value);
                    break;
                case 2:
                    stack.Push(value);
                    break;
                case 3:
                    stack.Push(-value);
                    break;
            }

            operation = (operation + 1) % 4;
        }

        int result = 0;

        while (stack.Count > 0) {
            result += stack.Pop();
        }

        return result;
    }
}
