public class MKAverage {
    private const int MaxValue = 100000;

    private readonly int m;
    private readonly int k;
    private readonly int[] countTree;
    private readonly long[] sumTree;
    private readonly System.Collections.Generic.Queue<int> window;

    public MKAverage(int m, int k) {
        this.m = m;
        this.k = k;
        countTree = new int[MaxValue + 1];
        sumTree = new long[MaxValue + 1];
        window = new System.Collections.Generic.Queue<int>();
    }

    public void AddElement(int num) {
        window.Enqueue(num);
        Update(num, 1);

        if (window.Count > m) {
            int removed = window.Dequeue();
            Update(removed, -1);
        }
    }

    public int CalculateMKAverage() {
        if (window.Count < m) {
            return -1;
        }

        long sumWithoutLargestK = SumSmallest(m - k);
        long sumOfSmallestK = SumSmallest(k);
        long middleSum = sumWithoutLargestK - sumOfSmallestK;

        return (int)(middleSum / (m - 2 * k));
    }

    private void Update(int value, int delta) {
        for (int i = value; i <= MaxValue; i += i & -i) {
            countTree[i] += delta;
            sumTree[i] += (long)value * delta;
        }
    }

    private long SumSmallest(int amount) {
        if (amount <= 0) {
            return 0;
        }

        int index = 0;
        int count = 0;
        long sum = 0;

        int step = 1;
        while ((step << 1) <= MaxValue) {
            step <<= 1;
        }

        for (; step > 0; step >>= 1) {
            int next = index + step;

            if (next <= MaxValue && count + countTree[next] < amount) {
                index = next;
                count += countTree[next];
                sum += sumTree[next];
            }
        }

        int boundaryValue = index + 1;
        return sum + (long)(amount - count) * boundaryValue;
    }
}
```

