public class Solution {
    public int[] NumSmallerByFrequency(string[] queries, string[] words) {
        int[] wordFrequencies = new int[words.Length];

        for (int i = 0; i < words.Length; i++) {
            wordFrequencies[i] = GetFrequency(words[i]);
        }

        System.Array.Sort(wordFrequencies);

        int[] answer = new int[queries.Length];

        for (int i = 0; i < queries.Length; i++) {
            int queryFrequency = GetFrequency(queries[i]);

            int left = 0;
            int right = wordFrequencies.Length;

            while (left < right) {
                int mid = left + (right - left) / 2;

                if (wordFrequencies[mid] <= queryFrequency) {
                    left = mid + 1;
                } else {
                    right = mid;
                }
            }

            answer[i] = wordFrequencies.Length - left;
        }

        return answer;
    }

    private int GetFrequency(string s) {
        char smallest = s[0];
        int frequency = 1;

        for (int i = 1; i < s.Length; i++) {
            if (s[i] < smallest) {
                smallest = s[i];
                frequency = 1;
            } else if (s[i] == smallest) {
                frequency++;
            }
        }

        return frequency;
    }
}
