public class Solution {
    public bool CanCross(int[] stones) {
        int n = stones.Length;

        if (stones[1] != 1) {
            return false;
        }

        var indexByPosition = new System.Collections.Generic.Dictionary<int, int>(n);
        for (int i = 0; i < n; i++) {
            indexByPosition[stones[i]] = i;
        }

        bool[][] dp = new bool[n][];
        for (int i = 0; i < n; i++) {
            dp[i] = new bool[n + 1];
        }

        dp[0][0] = true;

        for (int i = 0; i < n; i++) {
            for (int lastJump = 0; lastJump <= i; lastJump++) {
                if (!dp[i][lastJump]) {
                    continue;
                }

                for (int nextJump = lastJump - 1; nextJump <= lastJump + 1; nextJump++) {
                    if (nextJump <= 0 || nextJump > n) {
                        continue;
                    }

                    long nextPosition = (long)stones[i] + nextJump;
                    if (nextPosition > int.MaxValue) {
                        continue;
                    }

                    if (indexByPosition.TryGetValue((int)nextPosition, out int nextIndex)) {
                        if (nextIndex == n - 1) {
                            return true;
                        }

                        dp[nextIndex][nextJump] = true;
                    }
                }
            }
        }

        return false;
    }
}
