public class Solution {
    public int MaxScore(int[] nums) {
        int length = nums.Length;
        int[,] gcd = new int[length, length];

        for (int i = 0; i < length; i++) {
            for (int j = i + 1; j < length; j++) {
                int a = nums[i];
                int b = nums[j];

                while (b != 0) {
                    int remainder = a % b;
                    a = b;
                    b = remainder;
                }

                gcd[i, j] = a;
            }
        }

        int totalMasks = 1 << length;
        int[] dp = new int[totalMasks];
        int[] bitCount = new int[totalMasks];

        for (int mask = 1; mask < totalMasks; mask++) {
            dp[mask] = -1;
            bitCount[mask] = bitCount[mask >> 1] + (mask & 1);
        }

        dp[0] = 0;

        for (int mask = 0; mask < totalMasks; mask++) {
            if (dp[mask] < 0 || (bitCount[mask] & 1) != 0) {
                continue;
            }

            int operation = bitCount[mask] / 2 + 1;
            if (operation > length / 2) {
                continue;
            }

            for (int i = 0; i < length; i++) {
                if ((mask & (1 << i)) != 0) {
                    continue;
                }

                for (int j = i + 1; j < length; j++) {
                    if ((mask & (1 << j)) != 0) {
                        continue;
                    }

                    int nextMask = mask | (1 << i) | (1 << j);
                    int score = dp[mask] + operation * gcd[i, j];

                    if (score > dp[nextMask]) {
                        dp[nextMask] = score;
                    }
                }
            }
        }

        return dp[totalMasks - 1];
    }
}
