    public int CountVowelSubstrings(string word) {
        int[] last = { -1, -1, -1, -1, -1 };
        int lastConsonant = -1;
        int result = 0;

        for (int i = 0; i < word.Length; i++) {
            int vowelIndex;

            switch (word[i]) {
                case 'a': vowelIndex = 0; break;
                case 'e': vowelIndex = 1; break;
                case 'i': vowelIndex = 2; break;
                case 'o': vowelIndex = 3; break;
                case 'u': vowelIndex = 4; break;
                default: vowelIndex = -1; break;
            }

            if (vowelIndex == -1) {
                lastConsonant = i;
                continue;
            }

            last[vowelIndex] = i;

            int earliestLastOccurrence = last[0];
            for (int j = 1; j < 5; j++) {
                earliestLastOccurrence = System.Math.Min(
                    earliestLastOccurrence, last[j]
                );
            }

            if (earliestLastOccurrence > lastConsonant) {
                result += earliestLastOccurrence - lastConsonant;
            }
        }

        return result;
    }
