public class Solution {
    public int MaximumANDSum(int[] nums, int numSlots) {
        int[] powersOfThree = new int[numSlots + 1];
        powersOfThree[0] = 1;

        for (int i = 1; i <= numSlots; i++) {
            powersOfThree[i] = powersOfThree[i - 1] * 3;
        }

        int stateCount = powersOfThree[numSlots];
        int[] dp = new int[stateCount];
        int[] next = new int[stateCount];

        System.Array.Fill(dp, -1);
        dp[0] = 0;

        foreach (int num in nums) {
            System.Array.Fill(next, -1);

            for (int state = 0; state < stateCount; state++) {
                if (dp[state] < 0) {
                    continue;
                }

                for (int slot = 0; slot < numSlots; slot++) {
                    int occupancy = (state / powersOfThree[slot]) % 3;
                    if (occupancy == 2) {
                        continue;
                    }

                    int nextState = state + powersOfThree[slot];
                    int score = dp[state] + (num & (slot + 1));

                    if (score > next[nextState]) {
                        next[nextState] = score;
                    }
                }
            }

            int[] temp = dp;
            dp = next;
            next = temp;
        }

        int answer = 0;
        for (int state = 0; state < stateCount; state++) {
            if (dp[state] > answer) {
                answer = dp[state];
            }
        }

        return answer;
    }
}
