/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     public int val;
 *     public TreeNode left;
 *     public TreeNode right;
 *     public TreeNode(int val=0, TreeNode left=null, TreeNode right=null) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
public class Solution {
    public bool IsCousins(TreeNode root, int x, int y) {
        var nodes = new System.Collections.Generic.Queue<TreeNode>();
        var parents = new System.Collections.Generic.Queue<TreeNode>();

        nodes.Enqueue(root);
        parents.Enqueue(null);

        while (nodes.Count > 0) {
            int levelSize = nodes.Count;
            bool foundX = false;
            bool foundY = false;
            TreeNode parentX = null;
            TreeNode parentY = null;

            for (int i = 0; i < levelSize; i++) {
                TreeNode node = nodes.Dequeue();
                TreeNode parent = parents.Dequeue();

                if (node.val == x) {
                    foundX = true;
                    parentX = parent;
                }

                if (node.val == y) {
                    foundY = true;
                    parentY = parent;
                }

                if (node.left != null) {
                    nodes.Enqueue(node.left);
                    parents.Enqueue(node);
                }

                if (node.right != null) {
                    nodes.Enqueue(node.right);
                    parents.Enqueue(node);
                }
            }

            if (foundX || foundY) {
                return foundX && foundY && parentX != parentY;
            }
        }

        return false;
    }
}
