public class Solution {
    public int MaxTotalFruits(int[][] fruits, int startPos, int k) {
        int left = 0;
        int current = 0;
        int result = 0;

        for (int right = 0; right < fruits.Length; right++) {
            current += fruits[right][1];

            while (left <= right) {
                int leftPos = fruits[left][0];
                int rightPos = fruits[right][0];
                int steps = rightPos - leftPos
                    + System.Math.Min(
                        System.Math.Abs(startPos - leftPos),
                        System.Math.Abs(startPos - rightPos)
                    );

                if (steps <= k) {
                    break;
                }

                current -= fruits[left][1];
                left++;
            }

            result = System.Math.Max(result, current);
        }

        return result;
    }
}
