public class Solution {
    public IList<int> EventualSafeNodes(int[][] graph) {
        int n = graph.Length;
        int[] outDegree = new int[n];
        List<int>[] reverseGraph = new List<int>[n];

        for (int i = 0; i < n; i++) {
            reverseGraph[i] = new List<int>();
        }

        for (int node = 0; node < n; node++) {
            outDegree[node] = graph[node].Length;

            foreach (int neighbor in graph[node]) {
                reverseGraph[neighbor].Add(node);
            }
        }

        Queue<int> queue = new Queue<int>();
        bool[] safe = new bool[n];

        for (int node = 0; node < n; node++) {
            if (outDegree[node] == 0) {
                queue.Enqueue(node);
            }
        }

        while (queue.Count > 0) {
            int node = queue.Dequeue();
            safe[node] = true;

            foreach (int predecessor in reverseGraph[node]) {
                outDegree[predecessor]--;

                if (outDegree[predecessor] == 0) {
                    queue.Enqueue(predecessor);
                }
            }
        }

        List<int> result = new List<int>();

        for (int node = 0; node < n; node++) {
            if (safe[node]) {
                result.Add(node);
            }
        }

        return result;
    }
}
