public class Solution {
    public int LargestMagicSquare(int[][] grid) {
        int m = grid.Length;
        int n = grid[0].Length;

        long[,] rowPrefix = new long[m, n + 1];
        long[,] colPrefix = new long[m + 1, n];
        long[,] mainDiagPrefix = new long[m + 1, n + 1];
        long[,] antiDiagPrefix = new long[m + 1, n + 1];

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                long value = grid[r][c];
                rowPrefix[r, c + 1] = rowPrefix[r, c] + value;
                colPrefix[r + 1, c] = colPrefix[r, c] + value;
                mainDiagPrefix[r + 1, c + 1] = mainDiagPrefix[r, c] + value;
                antiDiagPrefix[r + 1, c] = antiDiagPrefix[r, c + 1] + value;
            }
        }

        for (int size = System.Math.Min(m, n); size >= 1; size--) {
            for (int r = 0; r + size <= m; r++) {
                for (int c = 0; c + size <= n; c++) {
                    long target = rowPrefix[r, c + size] - rowPrefix[r, c];

                    long mainDiagonal =
                        mainDiagPrefix[r + size, c + size] -
                        mainDiagPrefix[r, c];

                    long antiDiagonal =
                        antiDiagPrefix[r + size, c] -
                        antiDiagPrefix[r, c + size];

                    if (mainDiagonal != target || antiDiagonal != target) {
                        continue;
                    }

                    bool isMagic = true;

                    for (int i = 0; i < size && isMagic; i++) {
                        long rowSum =
                            rowPrefix[r + i, c + size] -
                            rowPrefix[r + i, c];

                        long columnSum =
                            colPrefix[r + size, c + i] -
                            colPrefix[r, c + i];

                        if (rowSum != target || columnSum != target) {
                            isMagic = false;
                        }
                    }

                    if (isMagic) {
                        return size;
                    }
                }
            }
        }

        return 1;
    }
}
