public class Solution {
    public int MaxStudents(char[][] seats) {
        int rows = seats.Length;
        int cols = seats[0].Length;
        int limit = 1 << cols;

        int[] bitCount = new int[limit];
        for (int mask = 1; mask < limit; mask++) {
            bitCount[mask] = bitCount[mask >> 1] + (mask & 1);
        }

        int[] dp = new int[limit];
        System.Array.Fill(dp, -1);
        dp[0] = 0;

        for (int row = 0; row < rows; row++) {
            int available = 0;
            for (int col = 0; col < cols; col++) {
                if (seats[row][col] == '.') {
                    available |= 1 << col;
                }
            }

            int[] next = new int[limit];
            System.Array.Fill(next, -1);

            for (int current = 0; current < limit; current++) {
                if ((current & ~available) != 0 ||
                    (current & (current << 1)) != 0) {
                    continue;
                }

                for (int previous = 0; previous < limit; previous++) {
                    if (dp[previous] < 0) {
                        continue;
                    }

                    if ((current & (previous << 1)) != 0 ||
                        (current & (previous >> 1)) != 0) {
                        continue;
                    }

                    next[current] = System.Math.Max(
                        next[current],
                        dp[previous] + bitCount[current]
                    );
                }
            }

            dp = next;
        }

        int answer = 0;
        for (int mask = 0; mask < limit; mask++) {
            answer = System.Math.Max(answer, dp[mask]);
        }

        return answer;
    }
}
