public class Solution {
    public long MaximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial) {
        int[] sorted = (int[])flowers.Clone();
        System.Array.Sort(sorted);

        int n = sorted.Length;
        int incompleteCount = 0;

        while (incompleteCount < n && sorted[incompleteCount] < target) {
            incompleteCount++;
        }

        long[] prefix = new long[incompleteCount + 1];
        for (int i = 0; i < incompleteCount; i++) {
            prefix[i + 1] = prefix[i] + sorted[i];
        }

        long answer = 0;
        long completionCost = 0;

        for (int completed = 0; completed <= incompleteCount; completed++) {
            if (completionCost > newFlowers) {
                break;
            }

            int remaining = incompleteCount - completed;
            long beauty = (long)(n - remaining) * full;

            if (remaining > 0) {
                long budget = newFlowers - completionCost;
                int low = 0;
                int high = target - 1;
                int bestMinimum = 0;

                while (low <= high) {
                    int middle = low + (high - low) / 2;

                    int left = 0;
                    int right = remaining;
                    while (left < right) {
                        int midIndex = left + (right - left) / 2;
                        if (sorted[midIndex] <= middle) {
                            left = midIndex + 1;
                        } else {
                            right = midIndex;
                        }
                    }

                    int count = left;
                    long required = (long)middle * count - prefix[count];

                    if (required <= budget) {
                        bestMinimum = middle;
                        low = middle + 1;
                    } else {
                        high = middle - 1;
                    }
                }

                beauty += (long)bestMinimum * partial;
            }

            answer = System.Math.Max(answer, beauty);

            if (completed < incompleteCount) {
                int index = incompleteCount - 1 - completed;
                completionCost += target - sorted[index];
            }
        }

        return answer;
    }
}
