            if (infected[i]) continue;

            for (int j = i + 1; j < n; j++) {
                if (!infected[j] && graph[i][j] == 1) {
                    dsu.Union(i, j);
                }
            }
        }

        int[] owner = new int[n];
        for (int i = 0; i < n; i++) {
            owner[i] = -1;
        }

        foreach (int malware in initial) {
            for (int node = 0; node < n; node++) {
                if (infected[node] || graph[malware][node] == 0) continue;

                int root = dsu.Find(node);

                if (owner[root] == -1) {
                    owner[root] = malware;
                } else if (owner[root] != malware) {
                    owner[root] = -2;
                }
            }
        }

        int[] saved = new int[n];

        for (int node = 0; node < n; node++) {
            if (infected[node] || dsu.Find(node) != node) continue;

            if (owner[node] >= 0) {
                saved[owner[node]] += dsu.GetSize(node);
            }
        }

        int answer = int.MaxValue;
        int bestSaved = -1;

        foreach (int malware in initial) {
            if (saved[malware] > bestSaved ||
                (saved[malware] == bestSaved && malware < answer)) {
                bestSaved = saved[malware];
                answer = malware;
            }
        }

        return answer;
    }

    private class DisjointSet {
        private readonly int[] parent;
        private readonly int[] size;

        public DisjointSet(int n) {
            parent = new int[n];
            size = new int[n];

            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int Find(int node) {
            if (parent[node] != node) {
                parent[node] = Find(parent[node]);
            }

            return parent[node];
        }

        public void Union(int a, int b) {
            int rootA = Find(a);
            int rootB = Find(b);

            if (rootA == rootB) return;

            if (size[rootA] < size[rootB]) {
                int temp = rootA;
                rootA = rootB;
                rootB = temp;
            }

            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        public int GetSize(int node) {
            return size[Find(node)];
        }
    }
}
