public class Solution {
    public int MinCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = passingFees.Length;
        const int INF = int.MaxValue / 2;

        int[][] dp = new int[maxTime + 1][];
        for (int time = 0; time <= maxTime; time++) {
            dp[time] = new int[n];
            for (int city = 0; city < n; city++) {
                dp[time][city] = INF;
            }
        }

        dp[0][0] = passingFees[0];

        for (int time = 0; time <= maxTime; time++) {
            foreach (int[] edge in edges) {
                int from = edge[0];
                int to = edge[1];
                int arrivalTime = time + edge[2];

                if (arrivalTime > maxTime) {
                    continue;
                }

                if (dp[time][from] != INF) {
                    dp[arrivalTime][to] = System.Math.Min(
                        dp[arrivalTime][to],
                        dp[time][from] + passingFees[to]
                    );
                }

                if (dp[time][to] != INF) {
                    dp[arrivalTime][from] = System.Math.Min(
                        dp[arrivalTime][from],
                        dp[time][to] + passingFees[from]
                    );
                }
            }
        }

        int answer = INF;
        for (int time = 0; time <= maxTime; time++) {
            answer = System.Math.Min(answer, dp[time][n - 1]);
        }

        return answer == INF ? -1 : answer;
    }
}
