public class Solution {
    private int[][] grid;
    private int rows;
    private int cols;

    public int MinDays(int[][] grid) {
        this.grid = grid;
        rows = grid.Length;
        cols = grid[0].Length;

        if (CountIslands() != 1) {
            return 0;
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 0) {
                    continue;
                }

                grid[r][c] = 0;

                if (CountIslands() != 1) {
                    grid[r][c] = 1;
                    return 1;
                }

                grid[r][c] = 1;
            }
        }

        return 2;
    }

    private int CountIslands() {
        bool[,] visited = new bool[rows, cols];
        int islands = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 1 && !visited[r, c]) {
                    islands++;

                    if (islands > 1) {
                        return islands;
                    }

                    Dfs(r, c, visited);
                }
            }
        }

        return islands;
    }

    private void Dfs(int r, int c, bool[,] visited) {
        if (r < 0 || r >= rows || c < 0 || c >= cols ||
            grid[r][c] == 0 || visited[r, c]) {
            return;
        }

        visited[r, c] = true;

        Dfs(r + 1, c, visited);
        Dfs(r - 1, c, visited);
        Dfs(r, c + 1, visited);
        Dfs(r, c - 1, visited);
    }
}
