public class Solution {
    public int MaxCompatibilitySum(int[][] students, int[][] mentors) {
        int m = students.Length;
        int n = students[0].Length;
        int[,] scores = new int[m, m];

        for (int student = 0; student < m; student++) {
            for (int mentor = 0; mentor < m; mentor++) {
                for (int question = 0; question < n; question++) {
                    if (students[student][question] == mentors[mentor][question]) {
                        scores[student, mentor]++;
                    }
                }
            }
        }

        int totalMasks = 1 << m;
        int[] dp = new int[totalMasks];

        for (int mask = 1; mask < totalMasks; mask++) {
            dp[mask] = -1;
        }

        for (int mask = 0; mask < totalMasks; mask++) {
            int student = 0;
            int value = mask;

            while (value != 0) {
                student += value & 1;
                value >>= 1;
            }

            if (student == m) {
                continue;
            }

            for (int mentor = 0; mentor < m; mentor++) {
                if ((mask & (1 << mentor)) == 0) {
                    int nextMask = mask | (1 << mentor);
                    int candidate = dp[mask] + scores[student, mentor];

                    if (candidate > dp[nextMask]) {
                        dp[nextMask] = candidate;
                    }
                }
            }
        }

        return dp[totalMasks - 1];
    }
}
