public class Solution {
    private const long Mod = 1000000007;
    private long[,] combinations;

    public int NumOfWays(int[] nums) {
        int n = nums.Length;
        combinations = new long[n + 1, n + 1];

        for (int i = 0; i <= n; i++) {
            combinations[i, 0] = 1;
            combinations[i, i] = 1;

            for (int j = 1; j < i; j++) {
                combinations[i, j] =
                    (combinations[i - 1, j - 1] + combinations[i - 1, j]) % Mod;
            }
        }

        var values = new System.Collections.Generic.List<int>(nums);
        long ways = CountWays(values);

        return (int)((ways - 1 + Mod) % Mod);
    }

    private long CountWays(System.Collections.Generic.List<int> values) {
        if (values.Count <= 2) {
            return 1;
        }

        int root = values[0];
        var left = new System.Collections.Generic.List<int>();
        var right = new System.Collections.Generic.List<int>();

        for (int i = 1; i < values.Count; i++) {
            if (values[i] < root) {
                left.Add(values[i]);
            } else {
                right.Add(values[i]);
            }
        }

        long leftWays = CountWays(left);
        long rightWays = CountWays(right);
        long interleavings = combinations[values.Count - 1, left.Count];

        return ((interleavings * leftWays) % Mod * rightWays) % Mod;
    }
}
