    public int MinDays(int[] bloomDay, int m, int k) {
        if ((long)m * k > bloomDay.Length) {
            return -1;
        }

        int left = bloomDay[0];
        int right = bloomDay[0];

        foreach (int day in bloomDay) {
            if (day < left) left = day;
            if (day > right) right = day;
        }

        while (left < right) {
            int mid = left + (right - left) / 2;

            int bouquets = 0;
            int adjacent = 0;

            foreach (int day in bloomDay) {
                if (day <= mid) {
                    adjacent++;
                    if (adjacent == k) {
