public class Solution {
    public bool[] FriendRequests(int n, int[][] restrictions, int[][] requests) {
        int[] parent = new int[n];
        int[] size = new int[n];

        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        bool[] result = new bool[requests.Length];

        for (int i = 0; i < requests.Length; i++) {
            int rootU = Find(parent, requests[i][0]);
            int rootV = Find(parent, requests[i][1]);

            if (rootU == rootV) {
                result[i] = true;
                continue;
            }

            bool allowed = true;

            foreach (int[] restriction in restrictions) {
                int rootX = Find(parent, restriction[0]);
                int rootY = Find(parent, restriction[1]);

                if ((rootX == rootU && rootY == rootV) ||
                    (rootX == rootV && rootY == rootU)) {
                    allowed = false;
                    break;
                }
            }

            if (!allowed) {
                continue;
            }

            result[i] = true;

            if (size[rootU] < size[rootV]) {
                int temp = rootU;
                rootU = rootV;
                rootV = temp;
            }

            parent[rootV] = rootU;
            size[rootU] += size[rootV];
        }

        return result;
    }

    private int Find(int[] parent, int node) {
        while (parent[node] != node) {
            parent[node] = parent[parent[node]];
            node = parent[node];
        }

        return node;
    }
}
