using System.Collections.Generic;
using System.Text;

public class Solution {
    public IList<string> RemoveInvalidParentheses(string s) {
        int leftRem = 0;
        int rightRem = 0;

        foreach (char c in s) {
            if (c == '(') {
                leftRem++;
            } else if (c == ')') {
                if (leftRem > 0) {
                    leftRem--;
                } else {
                    rightRem++;
                }
            }
        }

        var results = new HashSet<string>();
        var current = new StringBuilder();

        void Backtrack(int index, int balance, int removeLeft, int removeRight) {
            if (removeLeft + removeRight > s.Length - index) {
                return;
            }

            if (index == s.Length) {
                if (balance == 0 && removeLeft == 0 && removeRight == 0) {
                    results.Add(current.ToString());
                }
                return;
            }

            char c = s[index];

            if (c == '(') {
                if (removeLeft > 0) {
                    Backtrack(index + 1, balance, removeLeft - 1, removeRight);
                }

                current.Append(c);
                Backtrack(index + 1, balance + 1, removeLeft, removeRight);
                current.Length--;
            } else if (c == ')') {
                if (removeRight > 0) {
                    Backtrack(index + 1, balance, removeLeft, removeRight - 1);
                }

                if (balance > 0) {
                    current.Append(c);
                    Backtrack(index + 1, balance - 1, removeLeft, removeRight);
                    current.Length--;
                }
            } else {
                current.Append(c);
                Backtrack(index + 1, balance, removeLeft, removeRight);
                current.Length--;
            }
        }

        Backtrack(0, 0, leftRem, rightRem);
        return new List<string>(results);
    }
}
