public class Solution {
    public bool IsScramble(string s1, string s2) {
        int n = s1.Length;
        var memo = new byte[n, n, n + 1];
        var prefix1 = new int[n + 1, 26];
        var prefix2 = new int[n + 1, 26];

        for (int i = 0; i < n; i++) {
            for (int c = 0; c < 26; c++) {
                prefix1[i + 1, c] = prefix1[i, c];
                prefix2[i + 1, c] = prefix2[i, c];
            }

            prefix1[i + 1, s1[i] - 'a']++;
            prefix2[i + 1, s2[i] - 'a']++;
        }

        bool HaveSameCharacters(int i, int j, int length) {
            for (int c = 0; c < 26; c++) {
                int count1 = prefix1[i + length, c] - prefix1[i, c];
                int count2 = prefix2[j + length, c] - prefix2[j, c];

                if (count1 != count2) {
                    return false;
                }
            }

            return true;
        }

        bool Dfs(int i, int j, int length) {
            if (memo[i, j, length] != 0) {
                return memo[i, j, length] == 1;
            }

            bool identical = true;
            for (int k = 0; k < length; k++) {
                if (s1[i + k] != s2[j + k]) {
                    identical = false;
                    break;
                }
            }

            if (identical) {
                memo[i, j, length] = 1;
                return true;
            }

            if (!HaveSameCharacters(i, j, length)) {
                memo[i, j, length] = 2;
                return false;
            }

            for (int split = 1; split < length; split++) {
                bool withoutSwap =
                    Dfs(i, j, split) &&
                    Dfs(i + split, j + split, length - split);

                if (withoutSwap) {
                    memo[i, j, length] = 1;
                    return true;
                }

                bool withSwap =
                    Dfs(i, j + length - split, split) &&
                    Dfs(i + split, j, length - split);

                if (withSwap) {
                    memo[i, j, length] = 1;
                    return true;
                }
            }

            memo[i, j, length] = 2;
            return false;
        }

        return Dfs(0, 0, n);
    }
}
