using System.Collections.Generic;

public class Solution {
    public int NumTriplets(int[] nums1, int[] nums2) {
        long result = CountTriplets(nums1, nums2) + CountTriplets(nums2, nums1);
        return (int)result;
    }

    private long CountTriplets(int[] squaredNumbers, int[] productNumbers) {
        var frequencies = new Dictionary<int, int>();

        foreach (int number in squaredNumbers) {
            if (frequencies.ContainsKey(number)) {
                frequencies[number]++;
            } else {
                frequencies[number] = 1;
            }
        }

        long total = 0;

        foreach (var entry in frequencies) {
            long square = (long)entry.Key * entry.Key;
            var seen = new Dictionary<long, int>();
            long pairCount = 0;

            foreach (int number in productNumbers) {
                if (square % number == 0) {
                    long needed = square / number;
                    if (seen.TryGetValue(needed, out int count)) {
                        pairCount += count;
                    }
                }

                if (seen.ContainsKey(number)) {
                    seen[number]++;
                } else {
                    seen[number] = 1;
                }
            }

            total += pairCount * entry.Value;
        }

        return total;
    }
}
