    private struct Node {
        public int Value;
        public int Index;

        public Node(int value, int index) {
            Value = value;
            Index = index;
        }
    }

    private sealed class NodeComparer : System.Collections.Generic.IComparer<Node> {
        public int Compare(Node x, Node y) {
            int comparison = x.Value.CompareTo(y.Value);
            return comparison != 0 ? comparison : x.Index.CompareTo(y.Index);
        }
    }

    private System.Collections.Generic.SortedSet<Node> lower;
    private System.Collections.Generic.SortedSet<Node> upper;

    public double[] MedianSlidingWindow(int[] nums, int k) {
        lower = new System.Collections.Generic.SortedSet<Node>(new NodeComparer());
        upper = new System.Collections.Generic.SortedSet<Node>(new NodeComparer());

        double[] medians = new double[nums.Length - k + 1];

        for (int i = 0; i < k; i++) {
            Add(new Node(nums[i], i));
        }

        medians[0] = GetMedian(k);

        for (int i = k; i < nums.Length; i++) {
            Remove(new Node(nums[i - k], i - k));
            Add(new Node(nums[i], i));
            medians[i - k + 1] = GetMedian(k);
        }

        return medians;
    }

    private void Add(Node node) {
        if (lower.Count == 0 || Compare(node, lower.Max) <= 0) {
            lower.Add(node);
        } else {
            upper.Add(node);
        }

        Rebalance();
    }

    private void Remove(Node node) {
        if (!lower.Remove(node)) {
            upper.Remove(node);
        }

        Rebalance();
    }

    private void Rebalance() {
        while (lower.Count > upper.Count + 1) {
            Node node = lower.Max;
            lower.Remove(node);
            upper.Add(node);
        }

        while (lower.Count < upper.Count) {
            Node node = upper.Min;
            upper.Remove(node);
            lower.Add(node);
        }
    }

    private double GetMedian(int k) {
        if ((k & 1) == 1) {
            return lower.Max.Value;
        }

        return ((double)lower.Max.Value + (double)upper.Min.Value) / 2.0;
    }

