public class Solution {
    public IList<IList<int>> ShiftGrid(int[][] grid, int k) {
        int m = grid.Length;
        int n = grid[0].Length;
        int total = m * n;
        k %= total;

        IList<IList<int>> result = new List<IList<int>>();

        for (int row = 0; row < m; row++) {
            IList<int> currentRow = new List<int>();

            for (int col = 0; col < n; col++) {
