public class Solution {
    public bool CanPartitionKSubsets(int[] nums, int k) {
        int totalSum = 0;
        foreach (int num in nums) {
            totalSum += num;
        }

        if (totalSum % k != 0) {
            return false;
        }

        int target = totalSum / k;
        foreach (int num in nums) {
            if (num > target) {
                return false;
            }
        }

        int stateCount = 1 << nums.Length;
        int[] dp = new int[stateCount];
        System.Array.Fill(dp, -1);
        dp[0] = 0;

        for (int mask = 0; mask < stateCount; mask++) {
            if (dp[mask] == -1) {
                continue;
            }

            for (int i = 0; i < nums.Length; i++) {
                int bit = 1 << i;

                if ((mask & bit) != 0 || dp[mask] + nums[i] > target) {
                    continue;
                }

                int nextMask = mask | bit;
                dp[nextMask] = (dp[mask] + nums[i]) % target;
            }
        }

        return dp[stateCount - 1] == 0;
    }
}
