using System;
using System.Collections.Generic;
using System.Text;

public class Solution {
    private int[][] stickerCounts;
    private Dictionary<string, int> memo;

    public int MinStickers(string[] stickers, string target) {
        bool[] needed = new bool[26];
        foreach (char c in target) {
            needed[c - 'a'] = true;
        }

        var counts = new List<int[]>();
        bool[] available = new bool[26];

        foreach (string sticker in stickers) {
            int[] count = new int[26];
            foreach (char c in sticker) {
                int index = c - 'a';
                if (needed[index]) {
                    count[index]++;
                    available[index] = true;
                }
            }
            counts.Add(count);
        }

        foreach (char c in target) {
            if (!available[c - 'a']) {
                return -1;
            }
        }

        stickerCounts = counts.ToArray();
        memo = new Dictionary<string, int> {
            [""] = 0
        };

        char[] chars = target.ToCharArray();
        Array.Sort(chars);
        return Solve(new string(chars));
    }

    private int Solve(string remaining) {
        if (memo.TryGetValue(remaining, out int cached)) {
            return cached;
        }

        int[] required = new int[26];
        foreach (char c in remaining) {
            required[c - 'a']++;
        }

        int firstLetter = remaining[0] - 'a';
        int best = int.MaxValue;

        foreach (int[] sticker in stickerCounts) {
            if (sticker[firstLetter] == 0) {
                continue;
            }

            StringBuilder next = new StringBuilder();

            for (int i = 0; i < 26; i++) {
                int left = Math.Max(0, required[i] - sticker[i]);
                for (int j = 0; j < left; j++) {
                    next.Append((char)('a' + i));
                }
            }

            int result = Solve(next.ToString());
            if (result != -1) {
                best = Math.Min(best, result + 1);
            }
        }

        int answer = best == int.MaxValue ? -1 : best;
        memo[remaining] = answer;
        return answer;
    }
}
