public class Solution {
    public int RegionsBySlashes(string[] grid) {
        int n = grid.Length;
        int total = n * n * 4;
        int[] parent = new int[total];
        int[] rank = new int[total];

        for (int i = 0; i < total; i++) {
            parent[i] = i;
        }

        System.Func<int, int> find = null;
        find = x => {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        };

        System.Action<int, int> union = (a, b) => {
            int rootA = find(a);
            int rootB = find(b);

            if (rootA == rootB) return;

            if (rank[rootA] < rank[rootB]) {
                parent[rootA] = rootB;
            } else if (rank[rootA] > rank[rootB]) {
                parent[rootB] = rootA;
            } else {
                parent[rootB] = rootA;
                rank[rootA]++;
            }
        };

        for (int row = 0; row < n; row++) {
            for (int col = 0; col < n; col++) {
                int index = (row * n + col) * 4;
                char cell = grid[row][col];

                if (cell == ' ') {
                    union(index, index + 1);
                    union(index + 1, index + 2);
                    union(index + 2, index + 3);
                } else if (cell == '/') {
                    union(index, index + 3);
                    union(index + 1, index + 2);
                } else {
                    union(index, index + 1);
                    union(index + 2, index + 3);
                }

                if (row + 1 < n) {
                    int below = ((row + 1) * n + col) * 4;
                    union(index + 2, below);
                }

                if (col + 1 < n) {
                    int right = (row * n + col + 1) * 4;
                    union(index + 1, right + 3);
                }
            }
        }

        int regions = 0;
        for (int i = 0; i < total; i++) {
            if (find(i) == i) {
                regions++;
            }
        }

        return regions;
    }
