    private class TrieNode {
        public TrieNode[] Children = new TrieNode[26];
        public bool IsWord;
    }

    private readonly TrieNode root = new TrieNode();
    private readonly System.Text.StringBuilder stream = new System.Text.StringBuilder();
    private int maxWordLength;

    public StreamChecker(string[] words) {
        foreach (string word in words) {
            maxWordLength = System.Math.Max(maxWordLength, word.Length);

            TrieNode node = root;
            for (int i = word.Length - 1; i >= 0; i--) {
                int index = word[i] - 'a';

                if (node.Children[index] == null) {
                    node.Children[index] = new TrieNode();
                }

                node = node.Children[index];
            }

            node.IsWord = true;
        }
    }

    public bool Query(char letter) {
        stream.Append(letter);

        if (stream.Length > maxWordLength) {
            stream.Remove(0, stream.Length - maxWordLength);
        }

        TrieNode node = root;

        for (int i = stream.Length - 1; i >= 0; i--) {
            int index = stream[i] - 'a';
            node = node.Children[index];

            if (node == null) {
                return false;
            }

            if (node.IsWord) {
                return true;
            }
        }

        return false;
    }
}
