                graph[pair[0]] = new System.Collections.Generic.List<int>();
            }
            if (!graph.ContainsKey(pair[1])) {
                graph[pair[1]] = new System.Collections.Generic.List<int>();
            }

            graph[pair[0]].Add(pair[1]);
            graph[pair[1]].Add(pair[0]);
        }

        int start = 0;
        foreach (var entry in graph) {
            if (entry.Value.Count == 1) {
                start = entry.Key;
                break;
            }
        }

        int[] result = new int[adjacentPairs.Length + 1];
        result[0] = start;

        for (int i = 1; i < result.Length; i++) {
            var neighbors = graph[result[i - 1]];

            if (i == 1 || neighbors[0] != result[i - 2]) {
                result[i] = neighbors[0];
            } else {
                result[i] = neighbors[1];
            }
        }

        return result;
    }
}
