public class Solution {
    private readonly int[,,] earliestMemo = new int[29, 29, 29];
    private readonly int[,,] latestMemo = new int[29, 29, 29];

    public int[] EarliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        return Solve(n, firstPlayer, secondPlayer);
    }

    private int[] Solve(int count, int first, int second) {
        if (earliestMemo[count, first, second] != 0) {
            return new int[] {
                earliestMemo[count, first, second],
                latestMemo[count, first, second]
            };
        }

        if (first + second == count + 1) {
            earliestMemo[count, first, second] = 1;
            latestMemo[count, first, second] = 1;
            return new int[] { 1, 1 };
        }

        bool[,] possible = new bool[29, 29];
        possible[0, 0] = true;

        for (int left = 1; left <= count / 2; left++) {
            int right = count + 1 - left;

            if (left == first || left == second) {
                possible = Advance(possible, left, -1, first, second);
            } else if (right == first || right == second) {
                possible = Advance(possible, right, -1, first, second);
            } else {
                possible = Advance(possible, left, right, first, second);
            }
        }

        if ((count & 1) == 1) {
            int middle = count / 2 + 1;
            possible = Advance(possible, middle, -1, first, second);
        }

        int nextCount = (count + 1) / 2;
        int earliest = int.MaxValue;
        int latest = int.MinValue;

        for (int beforeFirst = 0; beforeFirst < 29; beforeFirst++) {
            for (int beforeSecond = 0; beforeSecond < 29; beforeSecond++) {
                if (!possible[beforeFirst, beforeSecond]) {
                    continue;
                }

                int nextFirst = beforeFirst + 1;
                int nextSecond = beforeSecond + 1;
                int[] result = Solve(nextCount, nextFirst, nextSecond);

                earliest = System.Math.Min(earliest, result[0] + 1);
                latest = System.Math.Max(latest, result[1] + 1);
            }
        }

        earliestMemo[count, first, second] = earliest;
        latestMemo[count, first, second] = latest;

        return new int[] { earliest, latest };
    }

    private bool[,] Advance(
        bool[,] current,
        int optionOne,
        int optionTwo,
        int first,
        int second
    ) {
        bool[,] next = new bool[29, 29];

        for (int beforeFirst = 0; beforeFirst < 29; beforeFirst++) {
            for (int beforeSecond = 0; beforeSecond < 29; beforeSecond++) {
                if (!current[beforeFirst, beforeSecond]) {
                    continue;
                }

                AddOption(next, beforeFirst, beforeSecond, optionOne, first, second);

                if (optionTwo != -1) {
                    AddOption(next, beforeFirst, beforeSecond, optionTwo, first, second);
                }
            }
        }

        return next;
    }

    private void AddOption(
        bool[,] next,
        int beforeFirst,
        int beforeSecond,
        int winnerPosition,
        int first,
        int second
    ) {
        int nextBeforeFirst = beforeFirst + (winnerPosition < first ? 1 : 0);
        int nextBeforeSecond = beforeSecond + (winnerPosition < second ? 1 : 0);
        next[nextBeforeFirst, nextBeforeSecond] = true;
    }
}
