public class Solution
{
    private struct DfsEvent
    {
        public int Node;
        public int Parent;
        public int Depth;
        public bool IsExit;

        public DfsEvent(int node, int parent, int depth, bool isExit)
        {
            Node = node;
            Parent = parent;
            Depth = depth;
            IsExit = isExit;
        }
    }

    public int[] GetCoprimes(int[] nums, int[][] edges)
    {
        int n = nums.Length;
        int[] answer = new int[n];
        int[] depth = new int[n];

        for (int i = 0; i < n; i++)
            answer[i] = -1;

        int[] head = new int[n];
        for (int i = 0; i < n; i++)
            head[i] = -1;

        int[] to = new int[edges.Length * 2];
        int[] next = new int[edges.Length * 2];
        int edgeIndex = 0;

        foreach (int[] edge in edges)
        {
            int u = edge[0];
            int v = edge[1];

            to[edgeIndex] = v;
            next[edgeIndex] = head[u];
            head[u] = edgeIndex++;

            to[edgeIndex] = u;
            next[edgeIndex] = head[v];
            head[v] = edgeIndex++;
        }

        bool[,] coprime = new bool[51, 51];
        for (int a = 1; a <= 50; a++)
        {
            for (int b = 1; b <= 50; b++)
                coprime[a, b] = Gcd(a, b) == 1;
        }

        var ancestorsByValue = new System.Collections.Generic.Stack<int>[51];
        for (int value = 1; value <= 50; value++)
            ancestorsByValue[value] = new System.Collections.Generic.Stack<int>();

        var events = new System.Collections.Generic.Stack<DfsEvent>();
        events.Push(new DfsEvent(0, -1, 0, false));

        while (events.Count > 0)
        {
            DfsEvent current = events.Pop();
            int node = current.Node;
            int value = nums[node];

            if (current.IsExit)
            {
                ancestorsByValue[value].Pop();
                continue;
            }

            depth[node] = current.Depth;

            int closestNode = -1;
            int closestDepth = -1;

            for (int ancestorValue = 1; ancestorValue <= 50; ancestorValue++)
            {
                if (!coprime[value, ancestorValue] ||
                    ancestorsByValue[ancestorValue].Count == 0)
                {
                    continue;
                }

                int candidate = ancestorsByValue[ancestorValue].Peek();
                if (depth[candidate] > closestDepth)
                {
                    closestDepth = depth[candidate];
                    closestNode = candidate;
                }
            }

            answer[node] = closestNode;
            ancestorsByValue[value].Push(node);

            events.Push(new DfsEvent(
                node, current.Parent, current.Depth, true));

            for (int edge = head[node]; edge != -1; edge = next[edge])
            {
                int neighbor = to[edge];
                if (neighbor == current.Parent)
                    continue;

                events.Push(new DfsEvent(
                    neighbor, node, current.Depth + 1, false));
            }
        }

        return answer;
    }

    private static int Gcd(int a, int b)
    {
        while (b != 0)
        {
            int remainder = a % b;
            a = b;
            b = remainder;
        }

        return a;
    }
}
