public class Solution {
    public int[][] SpiralMatrixIII(int rows, int cols, int rStart, int cStart) {
        int total = rows * cols;
        int[][] result = new int[total][];
        int index = 0;

        int row = rStart;
        int col = cStart;
        result[index++] = new int[] { row, col };

        int[] dr = { 0, 1, 0, -1 };
        int[] dc = { 1, 0, -1, 0 };
        int direction = 0;
        int stepLength = 1;

        while (index < total) {
            for (int twice = 0; twice < 2; twice++) {
                for (int step = 0; step < stepLength; step++) {
                    row += dr[direction];
                    col += dc[direction];

                    if (row >= 0 && row < rows && col >= 0 && col < cols) {
                        result[index++] = new int[] { row, col };

                        if (index == total) {
                            return result;
                        }
                    }
                }

                direction = (direction + 1) % 4;
            }

            stepLength++;
        }

        return result;
    }
}
