public class Solution {
    private string[] words;
    private string result;
    private int[] mapping;
    private bool[] used;
    private bool[] leading;

    public bool IsSolvable(string[] words, string result) {
        this.words = words;
        this.result = result;
        mapping = new int[26];
        used = new bool[10];
        leading = new bool[26];

        for (int i = 0; i < 26; i++) {
            mapping[i] = -1;
        }

        bool[] present = new bool[26];
        int distinct = 0;
        int maxWordLength = 0;

        foreach (string word in words) {
            maxWordLength = System.Math.Max(maxWordLength, word.Length);

            if (word.Length > 1) {
                leading[word[0] - 'A'] = true;
            }

            foreach (char ch in word) {
                int index = ch - 'A';
                if (!present[index]) {
                    present[index] = true;
                    distinct++;
                }
            }
        }

        if (result.Length > 1) {
            leading[result[0] - 'A'] = true;
        }

        foreach (char ch in result) {
            int index = ch - 'A';
            if (!present[index]) {
                present[index] = true;
                distinct++;
            }
        }

        if (distinct > 10 || maxWordLength > result.Length ||
            result.Length > maxWordLength + 1) {
            return false;
        }

        return Search(0, 0, 0);
    }

    private bool Search(int column, int wordIndex, int sum) {
        if (column == result.Length) {
            return sum == 0;
        }

        if (wordIndex < words.Length) {
            string word = words[wordIndex];
            int position = word.Length - 1 - column;

            if (position < 0) {
                return Search(column, wordIndex + 1, sum);
            }

            int letter = word[position] - 'A';

            if (mapping[letter] != -1) {
                return Search(column, wordIndex + 1, sum + mapping[letter]);
            }

            for (int digit = 0; digit <= 9; digit++) {
                if (used[digit] || (digit == 0 && leading[letter])) {
                    continue;
                }

                mapping[letter] = digit;
                used[digit] = true;

                if (Search(column, wordIndex + 1, sum + digit)) {
                    return true;
                }

                mapping[letter] = -1;
                used[digit] = false;
            }

            return false;
        }

        int resultPosition = result.Length - 1 - column;
        int resultLetter = result[resultPosition] - 'A';
        int requiredDigit = sum % 10;
        int carry = sum / 10;

        if (mapping[resultLetter] != -1) {
            if (mapping[resultLetter] != requiredDigit) {
                return false;
            }

            return Search(column + 1, 0, carry);
        }

        if (used[requiredDigit] ||
            (requiredDigit == 0 && leading[resultLetter])) {
            return false;
        }

        mapping[resultLetter] = requiredDigit;
        used[requiredDigit] = true;

        bool solvable = Search(column + 1, 0, carry);

        mapping[resultLetter] = -1;
        used[requiredDigit] = false;

        return solvable;
    }
}
