public class Solution {
    public bool ValidateBinaryTreeNodes(int n, int[] leftChild, int[] rightChild) {
        int[] indegree = new int[n];

        for (int i = 0; i < n; i++) {
            int left = leftChild[i];
            int right = rightChild[i];

            if (left != -1 && ++indegree[left] > 1) {
                return false;
            }

            if (right != -1 && ++indegree[right] > 1) {
                return false;
            }
        }

        int root = -1;
        for (int i = 0; i < n; i++) {
            if (indegree[i] == 0) {
                if (root != -1) {
                    return false;
                }
                root = i;
            }
        }

        if (root == -1) {
            return false;
        }

        bool[] visited = new bool[n];
        int[] stack = new int[n];
        int top = 0;
        int visitedCount = 0;
        stack[top++] = root;

        while (top > 0) {
            int node = stack[--top];

            if (visited[node]) {
                return false;
            }

            visited[node] = true;
            visitedCount++;

            if (leftChild[node] != -1) {
                stack[top++] = leftChild[node];
            }

            if (rightChild[node] != -1) {
                stack[top++] = rightChild[node];
            }
        }

        return visitedCount == n;
    }
}
