public class Solution {
    public int LadderLength(string beginWord, string endWord, IList<string> wordList) {
        var unvisited = new HashSet<string>(wordList);

        if (!unvisited.Contains(endWord)) {
            return 0;
        }

        var beginSet = new HashSet<string> { beginWord };
        var endSet = new HashSet<string> { endWord };

        unvisited.Remove(beginWord);
        unvisited.Remove(endWord);

        int length = 1;

        while (beginSet.Count > 0 && endSet.Count > 0) {
            if (beginSet.Count > endSet.Count) {
                var temp = beginSet;
                beginSet = endSet;
                endSet = temp;
            }

            var nextSet = new HashSet<string>();

            foreach (string word in beginSet) {
                char[] chars = word.ToCharArray();

                for (int i = 0; i < chars.Length; i++) {
                    char original = chars[i];

                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == original) {
                            continue;
                        }

                        chars[i] = c;
                        string candidate = new string(chars);

                        if (endSet.Contains(candidate)) {
                            return length + 1;
                        }

                        if (unvisited.Remove(candidate)) {
                            nextSet.Add(candidate);
                        }
                    }

                    chars[i] = original;
                }
            }

            beginSet = nextSet;
            length++;
        }

        return 0;
    }
}
